-- 071_test_couple_ex2_repair.sql
-- Generated by scripts/build-test-couple.mjs. Safe to re-run.
--
-- What this fixes: the seeded Expectations answers were written as 'me',
-- 'partner' and 'shared', which the exercise has never written. The product
-- stores the name of whoever does the thing, or "Both of us", or "Doesn't
-- apply to us". So the results table showed 'shared' where it should have said
-- "Both of us", and the alignment maths was comparing strings it did not
-- recognise.
--
-- It also adds what was missing from the seed entirely: what each of them grew
-- up with, and what "Both of us" turned out to mean.
--
-- It does NOT touch the tester's own answers, and it does NOT recompute the
-- deleted-partner account's frozen results row, which was written from the old
-- answers and is frozen by design.

update public.profiles set ex2_answers = '{"responsibilities":{"household__Cooking meals":"Both of us","household__Grocery shopping and meal planning":"Doesn''t apply to us","household__Keeping the home tidy day-to-day":"Tester","household__Managing home repairs and maintenance":"Testpartner","household__Managing the family calendar":"Tester","household__Planning and organizing social events, holidays, and gatherings":"Both of us","household__Planning and booking vacations":"Tester","financial__Paying bills and managing day-to-day finances":"Tester","financial__Making major financial decisions":"Doesn''t apply to us","financial__Managing savings and investments":"Doesn''t apply to us","financial__Filing taxes":"Tester","career__Being the primary income earner":"Tester","career__Whose career shapes major family decisions, where you live, your schedule, your lifestyle":"Tester","career__Who makes career sacrifices when the family needs it":"Tester","emotional__Carrying the mental load, remembering, anticipating, planning ahead":"Testpartner","emotional__Tracking the emotional wellbeing of the household":"Tester","extended_family__Planning visits with {userName}''s family":"Both of us","extended_family__Gifting for {userName}''s family":"Doesn''t apply to us","extended_family__Planning visits with {partnerName}''s family":"Tester","extended_family__Gifting for {partnerName}''s family":"Doesn''t apply to us"},"bothDetail":{"household__Cooking meals":"Genuinely 50/50","household__Planning and organizing social events, holidays, and gatherings":"Usually Testpartner, sometimes Tester","extended_family__Planning visits with {userName}''s family":"Usually Testpartner, sometimes Tester"},"life":{"lq_children":"Uncertain","lq_involve_user":"Minimal, by design","lq_involve_partner":"Very little, if any","lq_family_conf":"Keep the peace","lq_location":"Genuinely open","lq_social":"Very social","lq_routine":"Prefer open","lq_faith":"Meaningful role","lq_values":"Share broadly similar values","lq_finances":"Mostly separate, shared account for shared expenses","lq_money_lean":"Fully in the present","lq_money_risk":"Drawn to bold moves"},"childhood":{"household__Cooking meals":"N/A","household__Grocery shopping and meal planning":"N/A","household__Keeping the home tidy day-to-day":"Dad","household__Managing home repairs and maintenance":"Both","household__Managing the family calendar":"N/A","household__Planning and organizing social events, holidays, and gatherings":"N/A","household__Planning and booking vacations":"N/A","financial__Paying bills and managing day-to-day finances":"Dad","financial__Making major financial decisions":"N/A","financial__Managing savings and investments":"N/A","financial__Filing taxes":"Both","career__Being the primary income earner":"Dad","career__Whose career shapes major family decisions, where you live, your schedule, your lifestyle":"Mom","career__Who makes career sacrifices when the family needs it":"Mom","emotional__Carrying the mental load, remembering, anticipating, planning ahead":"Both","emotional__Tracking the emotional wellbeing of the household":"Dad"},"childhoodBothDetail":{"household__Managing home repairs and maintenance":"Genuinely 50/50","financial__Filing taxes":"Usually Mom, sometimes Dad","emotional__Carrying the mental load, remembering, anticipating, planning ahead":"Genuinely 50/50"},"childhoodStructure":"mom-dad"}'::jsonb
where id = '22222222-2222-4222-8222-222222222222';

update public.profiles set ex2_answers = '{"responsibilities":{"household__Cooking meals":"Departed","household__Grocery shopping and meal planning":"Both of us","household__Keeping the home tidy day-to-day":"Departed","household__Managing home repairs and maintenance":"Doesn''t apply to us","household__Managing the family calendar":"Solo","household__Planning and organizing social events, holidays, and gatherings":"Departed","household__Planning and booking vacations":"Departed","financial__Paying bills and managing day-to-day finances":"Departed","financial__Making major financial decisions":"Both of us","financial__Managing savings and investments":"Both of us","financial__Filing taxes":"Departed","career__Being the primary income earner":"Departed","career__Whose career shapes major family decisions, where you live, your schedule, your lifestyle":"Solo","career__Who makes career sacrifices when the family needs it":"Solo","emotional__Carrying the mental load, remembering, anticipating, planning ahead":"Doesn''t apply to us","emotional__Tracking the emotional wellbeing of the household":"Solo","extended_family__Planning visits with {userName}''s family":"Departed","extended_family__Gifting for {userName}''s family":"Both of us","extended_family__Planning visits with {partnerName}''s family":"Solo","extended_family__Gifting for {partnerName}''s family":"Both of us"},"bothDetail":{"household__Grocery shopping and meal planning":"Usually Solo, sometimes Departed","financial__Making major financial decisions":"Usually Solo, sometimes Departed","financial__Managing savings and investments":"Usually Solo, sometimes Departed","extended_family__Gifting for {userName}''s family":"Usually Solo, sometimes Departed","extended_family__Gifting for {partnerName}''s family":"Usually Departed, sometimes Solo"},"life":{"lq_children":"Not part of my future","lq_involve_user":"Very little, if any","lq_involve_partner":"Frequent, deeply integrated","lq_family_conf":"Defend family if right","lq_location":"Wherever makes sense for both","lq_social":"Pretty social","lq_routine":"Adapt easily","lq_faith":"Present but not imposed","lq_values":"Simply respect each other''s views","lq_finances":"Fully separate","lq_money_lean":"Lean toward spending","lq_money_risk":"Lean toward risk"},"childhood":{"household__Cooking meals":"Both","household__Grocery shopping and meal planning":"Both","household__Keeping the home tidy day-to-day":"Dad","household__Managing home repairs and maintenance":"Dad","household__Managing the family calendar":"Both","household__Planning and organizing social events, holidays, and gatherings":"Both","household__Planning and booking vacations":"Both","financial__Paying bills and managing day-to-day finances":"Mom","financial__Making major financial decisions":"Both","financial__Managing savings and investments":"Both","financial__Filing taxes":"Dad","career__Being the primary income earner":"Mom","career__Whose career shapes major family decisions, where you live, your schedule, your lifestyle":"N/A","career__Who makes career sacrifices when the family needs it":"N/A","emotional__Carrying the mental load, remembering, anticipating, planning ahead":"Dad","emotional__Tracking the emotional wellbeing of the household":"Mom"},"childhoodBothDetail":{"household__Cooking meals":"Usually Dad, sometimes Mom","household__Grocery shopping and meal planning":"Usually Mom, sometimes Dad","household__Managing the family calendar":"Usually Dad, sometimes Mom","household__Planning and organizing social events, holidays, and gatherings":"Usually Dad, sometimes Mom","household__Planning and booking vacations":"Usually Dad, sometimes Mom","financial__Making major financial decisions":"Genuinely 50/50","financial__Managing savings and investments":"Genuinely 50/50"},"childhoodStructure":"mom-dad"}'::jsonb
where id = '33333333-3333-4333-8333-333333333333';

-- ── Verification ───────────────────────────────────────────────────────────
-- Every stored answer should be a name, "Both of us" or "Doesn't apply to us".
select
  (select count(*) from jsonb_each_text((ex2_answers->'responsibilities')::jsonb)
     where value in ('me', 'partner', 'shared')) as old_vocabulary_left,
  (select count(*) from jsonb_each_text((ex2_answers->'responsibilities')::jsonb)) as answers,
  (select count(*) from jsonb_each_text((ex2_answers->'childhood')::jsonb))        as grew_up_with,
  (select count(*) from jsonb_each_text((ex2_answers->'bothDetail')::jsonb))       as both_refinements
from public.profiles where id = '22222222-2222-4222-8222-222222222222';
